<script setup lang="ts">import{ref}from"vue";import{get}from"../api";const q=ref(""),result=ref<any>(null);async function search(){result.value=await get(`/search?q=${encodeURIComponent(q.value)}`)}</script><template><h1>搜索与过滤</h1><div class="row"><input v-model="q" placeholder="搜索项目、任务或标签"><button @click="search">搜索</button></div><div v-if="result" class="panel">项目 {{result.projects.length}} 个，任务 {{result.tasks.length}} 个</div></template>
